function createVoxelTree(scale = 1.0) {
  const tree = new de();
  const trunkMat = Ie(0x744830);
  const leaf1 = Ie(0x8cb641);
  const leaf2 = Ie(0xa0cc4e);
  const leaf3 = Ie(0x769e32);
  const trunk = new H(new nt(0.35 * scale, 0.35 * scale, 1.8 * scale), trunkMat);
  trunk.position.set(0, 0, 0.9 * scale);
  trunk.castShadow = true;
  tree.add(trunk);
  const fol1 = new H(new nt(1.35 * scale, 1.35 * scale, 1.05 * scale), leaf1);
  fol1.position.set(0, 0, 1.9 * scale);
  fol1.rotation.z = 0.2;
  fol1.castShadow = true;
  tree.add(fol1);
  const fol2 = new H(new nt(1.0 * scale, 1.0 * scale, 0.85 * scale), leaf2);
  fol2.position.set(0.12 * scale, -0.08 * scale, 2.6 * scale);
  fol2.rotation.z = -0.15;
  fol2.castShadow = true;
  tree.add(fol2);
  const fol3 = new H(new nt(0.65 * scale, 0.65 * scale, 0.55 * scale), leaf3);
  fol3.position.set(-0.06 * scale, 0.08 * scale, 3.15 * scale);
  fol3.castShadow = true;
  tree.add(fol3);
  return tree;
}

function buildLowPolyVoxelWorld(scene) {
  const root = new de();
  root.name = "low_poly_voxel_world";
  const grassMat = Ie(0x90b84c);
  const grassAltMat = Ie(0x9ec953);
  const claySideMat = Ie(0xba674d);
  const bedrockMat = Ie(0x763825);
  const waterMat = new Ze({ color: 0x50b5d4, transparent: true, opacity: 0.68, roughness: 0.1 });
  const woodMat = Ie(0x9c5d3d);
  const rockMat = Ie(0xcec4d2);

  function createVoxelBlock(w, d, h, isAlt = false) {
    const geo = new nt(w, d, h);
    const topM = isAlt ? grassAltMat : grassMat;
    const mats = [claySideMat, claySideMat, claySideMat, claySideMat, topM, bedrockMat];
    const mesh = new H(geo, mats);
    mesh.receiveShadow = true;
    mesh.castShadow = true;
    return mesh;
  }

  // Base floating island slab supporting the station & road
  const baseBlock = createVoxelBlock(64, 80, 4.4);
  baseBlock.position.set(4, 0, -2.2);
  root.add(baseBlock);

  // Stepped island perimeter extensions
  const extensions = [
    [-24, -36, 16, 14, 4.2, 0.0],
    [-26, 32, 14, 18, 4.2, 0.0],
    [32, -32, 14, 18, 4.0, 0.0],
    [30, 30, 16, 16, 4.0, 0.0],
    [10, 42, 18, 12, 3.6, 0.0],
    [-8, -44, 20, 12, 3.6, 0.0],
    [-32, -10, 8, 26, 3.4, -0.6],
    [-30, 16, 8, 20, 3.0, -1.0],
    [36, -10, 8, 24, 3.2, -0.8],
    [34, 14, 8, 22, 2.8, -1.2],
    [5, -44, 14, 8, 2.6, -1.4],
    [4, 44, 16, 8, 2.6, -1.4]
  ];
  for (const [bx, by, bw, bd, bh, bzTop] of extensions) {
    const blk = createVoxelBlock(bw, bd, bh, (bx + by) % 2 === 0);
    blk.position.set(bx, by, bzTop - bh / 2);
    root.add(blk);
  }

  // Stepped terraces & hillocks
  const terraces = [
    { x: -19, y: -12, w: 14, d: 20, h: 1.4, z: 0.7, alt: false },
    { x: -21, y: 10, w: 12, d: 18, h: 1.4, z: 0.7, alt: true },
    { x: -22, y: -10, w: 10, d: 14, h: 1.4, z: 2.1, alt: false },
    { x: -23, y: 8, w: 8, d: 12, h: 1.4, z: 2.1, alt: false },
    { x: -23, y: -8, w: 6, d: 8, h: 1.4, z: 3.5, alt: true },
    { x: 22, y: 22, w: 14, d: 14, h: 1.5, z: 0.75, alt: false },
    { x: 24, y: 24, w: 9, d: 9, h: 1.5, z: 2.25, alt: true },
    { x: 25, y: 25, w: 5, d: 5, h: 1.4, z: 3.65, alt: false },
    { x: 22, y: -24, w: 14, d: 14, h: 1.4, z: 0.7, alt: true },
    { x: 24, y: -26, w: 9, d: 10, h: 1.4, z: 2.1, alt: false }
  ];
  for (const t of terraces) {
    const blk = createVoxelBlock(t.w, t.d, t.h, t.alt);
    blk.position.set(t.x, t.y, t.z);
    root.add(blk);
  }

  // Translucent water lagoons
  const waterPools = [
    { x: 28, y: -2, w: 12, d: 16, z: -0.2 },
    { x: -26, y: -30, w: 10, d: 12, z: -0.2 }
  ];
  for (const wp of waterPools) {
    const wMesh = new H(new nt(wp.w, wp.d, 0.5), waterMat);
    wMesh.position.set(wp.x, wp.y, wp.z);
    root.add(wMesh);
    for (let p = 0; p < 4; p++) {
      const plank = new H(new nt(2.4, 0.6, 0.12), woodMat);
      plank.position.set(wp.x - wp.w / 2 + 1.3, wp.y - 2.5 + p * 1.1, 0.08);
      plank.castShadow = true;
      root.add(plank);
    }
  }

  // Wooden ladders on cliff walls
  const ladders = [
    { x: -11.9, y: -12, z: 0.7, rot: 0, h: 1.4 },
    { x: -16.9, y: -10, z: 2.1, rot: 0, h: 1.4 },
    { x: 14.9, y: 22, z: 0.75, rot: 0, h: 1.5 },
    { x: 19.4, y: 24, z: 2.25, rot: 0, h: 1.5 },
    { x: 14.9, y: -24, z: 0.7, rot: 0, h: 1.4 }
  ];
  for (const lad of ladders) {
    const lGroup = new de();
    const railL = new H(new nt(0.06, 0.06, lad.h + 0.1), woodMat);
    railL.position.set(0, -0.22, 0);
    const railR = new H(new nt(0.06, 0.06, lad.h + 0.1), woodMat);
    railR.position.set(0, 0.22, 0);
    lGroup.add(railL, railR);
    for (let r = 0; r < 4; r++) {
      const rung = new H(new nt(0.05, 0.44, 0.05), woodMat);
      rung.position.set(0, 0, -lad.h / 2 + 0.2 + r * (lad.h / 4));
      lGroup.add(rung);
    }
    lGroup.position.set(lad.x, lad.y, lad.z);
    lGroup.rotation.z = lad.rot;
    root.add(lGroup);
  }

  // Scattered cubic rocks & pebbles
  const rockCoords = [
    [-17, -14, 1.4, 0.42], [-21, -6, 1.4, 0.35], [-23, 14, 1.4, 0.45],
    [-24, -9, 2.8, 0.38], [-21, 6, 2.8, 0.4], [-23, -8, 4.2, 0.32],
    [23, 20, 1.5, 0.35], [26, 27, 2.25, 0.42], [24, -20, 1.4, 0.35],
    [15, -7, 0.0, 0.28], [-8, 22, 0.0, 0.3], [12, 14, 0.0, 0.26]
  ];
  for (const [rx, ry, rz, rs] of rockCoords) {
    const rMesh = new H(new nt(rs, rs, rs * 0.85), rockMat);
    rMesh.position.set(rx, ry, rz + (rs * 0.42));
    rMesh.rotation.z = (rx * 4.7 + ry * 2.3) % Math.PI;
    rMesh.castShadow = true;
    root.add(rMesh);
  }

  // Voxel trees on elevated hill terraces
  const terraceTrees = [
    [-23, -8, 4.2, 1.1],
    [-22, 8, 2.8, 0.95],
    [-20, -14, 1.4, 1.0],
    [25, 25, 3.65, 1.0],
    [23, -24, 1.4, 0.9]
  ];
  for (const [tx, ty, tz, ts] of terraceTrees) {
    const tTree = createVoxelTree(ts);
    tTree.position.set(tx, ty, tz);
    tTree.rotation.z = (tx * 3.7 + ty * 2.1) % (Math.PI * 2);
    root.add(tTree);
  }

  scene.add(root);
  return root;
}

